body='\n\n'.join('## '+n['address']+' — '+n['proposed_name']+'\n\n'+n['summary_ru']+'\n\n'+'\n\n'.join(n['details_ru']) for n in functions)
(OUT/'contract.md').write_text(intro+'\n\n'+body+'\n',encoding='utf8')
